import time

class Breaker:
    def __init__(self, threshold: int = 5, cooldown_s: float = 30):
        self.fails, self.opened_at = 0, None
        self.threshold, self.cooldown = threshold, cooldown_s

    def allow(self) -> bool:        # after the cooldown, let traffic probe again
        return self.opened_at is None or time.monotonic() - self.opened_at > self.cooldown

    def record(self, ok: bool) -> None:
        self.fails = 0 if ok else self.fails + 1
        if ok:
            self.opened_at = None
        elif self.fails >= self.threshold:
            self.opened_at = time.monotonic()

# Each rung has its own prompt, evaluated on the golden set every week
LADDER = [("primary", call_primary, 20), ("backup", call_backup, 20), ("small", call_small, 8)]
breakers = {name: Breaker() for name, _, _ in LADDER}

def answer(msg: str) -> str:
    for name, call, timeout_s in LADDER:
        if not breakers[name].allow():
            continue                                  # fail fast, don't pile on
        try:
            out = call(msg, timeout=timeout_s)        # SDK retries 429/5xx with backoff
            breakers[name].record(True)
            metrics.incr("llm.served_by", tags={"rung": name})  # alert on fallback share
            return out
        except (TimeoutError, RateLimited, Overloaded, ServerError):
            breakers[name].record(False)
    return cached_answer(msg) or search_results(msg) or handoff_to_human(msg)
